# Generated by manage.py generate_test_cases.
import re
from unittest.mock import patch
from playwright.sync_api import expect
from bloomerp.tests.models.communication.voip.fixtures import VoIPFixtures
from bloomerp.communication.builtins.voip.definition import VoIPNumberData
from bloomerp.tests.base import BloomerpE2ETestCase, E2EAction, E2ERequestScenario


class TestCreateVoIpnumberViewE2E(VoIPFixtures, BloomerpE2ETestCase):
    """Exercise the connection tab and real purchase form without a paid carrier request."""

    view_name = "create_voip_number"

    def get_test_scenarios(self) -> list[E2ERequestScenario]:
        """Navigate from the connection tab to search, confirmation and the new line detail."""
        self.prepare_voip()
        adapter = self.enterContext(
            patch("bloomerp.communication.builtins.voip.controller.adapter_for")
        ).return_value
        self.enterContext(
            patch(
                "bloomerp.views.communication.create_voip_number.adapter_for",
                return_value=adapter,
            )
        )
        adapter.search_numbers.return_value = (
            VoIPNumberData("", "+32470000008", "Available line", True, True),
        )
        adapter.list_numbers.return_value = ()
        adapter.provision_number.return_value = VoIPNumberData(
            "PN" + "8" * 32, "+32470000008", "Reception", True, True
        )
        return [
            E2ERequestScenario(
                name="Provision a phone number from its connection",
                user=self.admin_user,
                url=self.connection.get_absolute_url(),
                actions=[
                    E2EAction(
                        name="Search and purchase a selected number",
                        execute=self.purchase,
                        validators=self.verify_number,
                    )
                ],
            )
        ]

    def purchase(self) -> None:
        """Use the detail tab and explicitly confirm the selected number's carrier charges."""
        expect(
            self.page.locator('[bloomerp-component="bloomerp:messaging-panel"]')
        ).to_have_attribute("data-component-initialized", "true")
        self.page.get_by_role("tab", name="Create phone number", exact=True).click()
        self.page.locator('input[name="country"]').fill("BE")
        self.page.locator('select[name="kind"]').select_option("mobile")
        with self.page.expect_response(re.compile(r"/phone-numbers/create/\?")) as search_response:
            self.page.get_by_role("button", name="Search available numbers").click()
        self.assertEqual(search_response.value.request.headers.get("hx-request"), "true")
        self.assertEqual(
            search_response.value.request.headers.get("hx-target"),
            "detail-view-content",
        )
        self.page.locator('input[name="selection"]').check()
        self.page.locator('#voip-number-purchase-form input[name="name"]').fill(
            "Reception"
        )
        self.page.locator('input[name="confirm"]').check()
        self.page.get_by_role("button", name="Create selected number").click()

    def verify_number(self) -> None:
        """Check the created line detail and retained staff assignment."""
        expect(
            self.page.get_by_text("Reception · +32470000008", exact=True).first
        ).to_be_visible()
        self.assertTrue(
            self.connection.numbers.filter(
                number="+32470000008", assigned_users=self.admin_user
            ).exists()
        )
